// Exploiting Temporal Locality in Caching

const int REUSE_COUNT = 10000;
const int CACHE_SET_SIZE = 8; // Small data set likely fits in L1/L2

int data[CACHE_SET_SIZE] = {0};
long sum = 0;

for (int iter = 0; iter < REUSE_COUNT; ++iter) {
    // Inner loop repeatedly accesses the *same* small set of memory
    // Data loaded in the first iteration stays hot in cache lines.
    for (int i = 0; i < CACHE_SET_SIZE; ++i) {
        data[i] = data[i] + 1; // High Temporal Locality (Cache Hit)
        sum += data[i];
    }
}
