cpp_op_return_value_optimization_rvo_and.code:
struct Expensive {
    Expensive() = default;
    Expensive(const Expensive&) = delete;
    Expensive(Expensive&&) = default; // Must be movable
};

// --- RVO (Guaranteed Copy Elision C++17+) ---
Expensive factory_rvo() {
    return Expensive(); // Direct construction, no temporary created
}

// --- NRVO (Named Return Value Optimization - Compiler Dependent) ---
Expensive factory_nrvo() {
    Expensive local_obj; // Named local variable
    // ... operations on local_obj
    return local_obj; // Compiler usually omits move/copy
}

// --- NRVO Prevention (Requires Move/Copy) ---
Expensive anti_nrvo(bool cond) {
    Expensive a, b;
    if (cond) return a;
    return b; // Optimization blocked: multiple named variables returned
}

